namespace ShipmentTracker.Client.Models;

public class Shipment
{
    public int Id { get; set; }
    public string TrackingNumber { get; set; } = string.Empty;
    public string Origin { get; set; } = string.Empty;
    public string Destination { get; set; } = string.Empty;
    public string Status { get; set; } = string.Empty;
    public DateTime? EstimatedDelivery { get; set; }
    public string CustomerEmail { get; set; } = string.Empty;
}

using ShipmentTracker.Client.Models;

namespace ShipmentTracker.Client.Services;

public interface IShipmentService
{
    Task<List<Shipment>> GetAllShipmentsAsync();
    Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber);
    Task UpdateShipmentStatusAsync(int id, string newStatus);
}

using System.Net.Http.Json;
using ShipmentTracker.Client.Models;

namespace ShipmentTracker.Client.Services;

public class ShipmentHttpService : IShipmentService
{
    private readonly HttpClient _httpClient;

    public ShipmentHttpService(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    public async Task<List<Shipment>> GetAllShipmentsAsync()
    {
        return await _httpClient.GetFromJsonAsync<List<Shipment>>("/api/shipments") ?? new List<Shipment>();
    }

    public async Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        var response = await _httpClient.GetAsync($"/api/shipments/{trackingNumber}");
        if (response.IsSuccessStatusCode)
        {
            return await response.Content.ReadFromJsonAsync<Shipment>();
        }
        return null;
    }

    public async Task UpdateShipmentStatusAsync(int id, string newStatus)
    {
        await _httpClient.PutAsJsonAsync($"/api/shipments/{id}/status", new { Status = newStatus });
    }
}

using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;

namespace ShipmentTracker.Services;

public class ShipmentServerService : IShipmentService
{
    private static readonly Lock _lock = new();
    private static readonly List<Shipment> _shipments = new()
    {
        new Shipment { Id = 1, TrackingNumber = "TRK-001", Origin = "New York", Destination = "Los Angeles", Status = "In Transit", EstimatedDelivery = DateTime.Now.AddDays(3), CustomerEmail = "alice@example.com" },
        new Shipment { Id = 2, TrackingNumber = "TRK-002", Origin = "Chicago", Destination = "Houston", Status = "Delivered", EstimatedDelivery = DateTime.Now.AddDays(-1), CustomerEmail = "bob@example.com" },
        new Shipment { Id = 3, TrackingNumber = "TRK-003", Origin = "Seattle", Destination = "Miami", Status = "Processing", EstimatedDelivery = DateTime.Now.AddDays(5), CustomerEmail = "carol@example.com" },
        new Shipment { Id = 4, TrackingNumber = "TRK-004", Origin = "Boston", Destination = "Denver", Status = "Out for Delivery", EstimatedDelivery = DateTime.Now, CustomerEmail = "dave@example.com" },
        new Shipment { Id = 5, TrackingNumber = "TRK-005", Origin = "San Francisco", Destination = "Atlanta", Status = "In Transit", EstimatedDelivery = DateTime.Now.AddDays(2), CustomerEmail = "eve@example.com" }
    };

    public Task<List<Shipment>> GetAllShipmentsAsync()
    {
        lock (_lock)
        {
            return Task.FromResult(_shipments.ToList());
        }
    }

    public Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        lock (_lock)
        {
            var shipment = _shipments.FirstOrDefault(s => s.TrackingNumber.Equals(trackingNumber, StringComparison.OrdinalIgnoreCase));
            return Task.FromResult(shipment);
        }
    }

    public Task UpdateShipmentStatusAsync(int id, string newStatus)
    {
        lock (_lock)
        {
            var shipment = _shipments.FirstOrDefault(s => s.Id == id);
            if (shipment is not null)
            {
                shipment.Status = newStatus;
            }
        }
        return Task.CompletedTask;
    }
}

namespace ShipmentTracker.Client.Models;

public class Shipment
{
    public int Id { get; set; }
    public string TrackingNumber { get; set; } = string.Empty;
    public string Origin { get; set; } = string.Empty;
    public string Destination { get; set; } = string.Empty;
