﻿@page "/"
@using Microsoft.AspNetCore.Authorization
@attribute [Authorize]

@inject IShipmentService ShipmentService

<PageTitle>Dispatcher Dashboard</PageTitle>

<h1>Dispatcher Dashboard</h1>

<div class="mb-3">
    <input type="text" class="form-control" placeholder="Filter by destination..." @bind="destinationFilter" @bind:event="oninput" />
</div>

@if (shipments is null)
{
    <p><em>Loading...</em></p>
}
else
{
    <table class="table table-striped">
        <thead>
            <tr>
                <th>Tracking Number</th>
                <th>Origin</th>
                <th>Destination</th>
                <th>Status</th>
                <th>Estimated Delivery</th>
                <th>Update Status</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var shipment in filteredShipments)
            {
                <tr>
                    <td>@shipment.TrackingNumber</td>
                    <td>@shipment.Origin</td>
                    <td>@shipment.Destination</td>
                    <td>@shipment.Status</td>
                    <td>@shipment.EstimatedDelivery?.ToString("yyyy-MM-dd")</td>
                    <td>
                        <select class="form-select" value="@shipment.Status" @onchange="(e) => UpdateStatus(shipment.Id, e.Value?.ToString() ?? string.Empty)">
                            <option value="Processing">Processing</option>
                            <option value="In Transit">In Transit</option>
                            <option value="Out for Delivery">Out for Delivery</option>
                            <option value="Delivered">Delivered</option>
                        </select>
                    </td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<Shipment>? shipments;
    private string destinationFilter = string.Empty;

    private IEnumerable<Shipment> filteredShipments =>
        shipments?.Where(s => string.IsNullOrWhiteSpace(destinationFilter)
            || s.Destination.Contains(destinationFilter, StringComparison.OrdinalIgnoreCase)) ?? Enumerable.Empty<Shipment>();

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }

    private async Task UpdateStatus(int id, string newStatus)
    {
        await ShipmentService.UpdateShipmentStatusAsync(id, newStatus);
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }
}

